        if (error) {
            console.log(`error: ${error.message}`);
            res.status(500).send('Error executing command');
            return;
        }
        if (stderr) {
            console.log(`stderr: ${stderr}`);
            res.status(500).send('Error executing command');
            return;
        }
        console.log(`stdout: ${stdout}`);
        res.send('Command executed successfully');
    });
});

