            SqlCommand command = new SqlCommand(sqlQuery, connection);
            command.Parameters.AddWithValue("@username", username);
            command.Parameters.AddWithValue("@password", hashedPassword);
            connection.Open();
            int count = (int)command.ExecuteScalar();

            return count > 0;
        }
