            command.Parameters.AddWithValue("@password", password);

            command.Connection.Open();
            SqlDataReader reader = command.ExecuteReader();

            if (reader.HasRows)
            {
                Console.WriteLine("Login successful!");
            }
            else
            {
                Console.WriteLine("Invalid login!");
            }

            reader.Close();
        }
    }
